insert into public.manual_parts (no,title,summary,sort) values
(1,'Legal mandate and governance','Mandate, structure, authorities and accountability of the CDRRMO, the CDRRMC and the EOC.',1),
(2,'SOPs by alert level','Preparedness, EOC activation, logistics and responder safety. The core of EOC operations and the largest Part.',2),
(3,'Information management and public communication','Risk intelligence, early warning and public information, situational awareness and GIS.',3),
(4,'Continuity and infrastructure safeguards','Digital continuity, cybersecurity and systems resilience.',4),
(5,'Recovery and continuous improvement','Recovery, learning, performance and manual revision.',5)
insert into public.manual_areas (no,part_no,title,scope,mcr_primary,mcr_supporting,sort) values
(1,1,'Governance, Organization & Institutional Arrangements','CDRRMO/EOC mandate; organizational structure; LDRRMC relationships; authorities; delegation; duty officers; ICS roles; inter-agency coordination; public-private partnerships; accountability','Essential 1 – Organize for Disaster Resilience','Essentials 6, 7, 9',1),
(3,2,'Preparedness, Planning & Capacity Development','Emergency plans; contingency plans; SOPs; preparedness standards; training; drills; simulations; competency requirements; EOC readiness; BDRRMC capacity; mutual-aid arrangements','Essential 6 – Strengthen Institutional Capacity for Resilience','Essentials 1, 7, 9',2),
(4,2,'EOC Activation, Incident Management & Coordination','Alert levels; activation/deactivation; ICS integration; incident objectives; command and coordination; operational periods; EOC staffing; escalation; transition from response to recovery','Essential 9 – Ensure Effective Disaster Response','Essentials 1, 6, 10',3),
(7,2,'Resource, Logistics & Emergency Support Management','Resource inventory; resource requests; procurement; stockpiling; staging; transport; warehousing; fuel; relief supplies; mutual aid; supplier networks; emergency support services','Essential 9 – Ensure Effective Disaster Response','Essentials 3, 8, 6',4),
(8,2,'Responder Safety, Welfare & Inclusive Emergency Operations','Duty of care; PPE; responder health and safety; psychosocial support; fatigue management; workforce rotation; gender/inclusion considerations; protection of vulnerable groups; safe operating procedures','Essential 9 – Ensure Effective Disaster Response','Essentials 6, 7, 8',5),
(2,3,'Risk Intelligence, Prevention & Mitigation','Multi-hazard risk assessment; hazard/exposure/vulnerability analysis; climate risk; risk scenarios; GIS-based risk information; prevention and mitigation measures; risk-informed development planning','Essential 2 – Identify, Understand and Use Current and Future Risk Scenarios','Essentials 4, 5, 8',6),
(5,3,'Early Warning, Emergency Communications & Public Information','Monitoring; detection; warning thresholds; multi-channel dissemination; public information; risk communication; accessible alerts; community feedback; rumor management; warning verification','Essential 9 – Ensure Effective Disaster Response','Essentials 2, 7, 6',7),
(6,3,'Situational Awareness, Information Management & GIS','Data collection; validation; common operating picture; GIS; dashboards; incident reports; SITREPs; data standards; information-sharing; decision support; risk intelligence','Essential 2 – Identify, Understand and Use Current and Future Risk Scenarios','Essentials 6, 9, 8',8),
(9,4,'Digital Continuity, Cybersecurity & Systems Resilience','Critical information systems; cybersecurity; data protection; backups; cloud redundancy; alternate communications; power continuity; disaster recovery; system interoperability; continuity of operations','Essential 8 – Increase Infrastructure Resilience','Essentials 6, 9, 4',9),
(10,5,'Recovery, Learning, Performance & Continuous Improvement','Recovery transition; damage/loss assessment; debris management; rehabilitation/reconstruction; Build Back Better; economic recovery; AARs; M&E; audits; exercises; lessons learned; manual revision','Essential 10 – Expedite Recovery and Build Back Better','Essentials 3, 6, 7, 8, 9',10)
